  "tree.trackingOff": {
    en: "Agent tracking is off, so no agents are listed. Turning it on adds hooks to ~/.claude/settings.json so ymux can show agents and subagents. You can turn it off again in Settings.",
    ko: "에이전트 추적이 꺼져 있어 에이전트가 표시되지 않습니다. 켜면 ~/.claude/settings.json에 훅을 추가해 ymux가 에이전트와 하위 에이전트를 표시합니다. 설정에서 다시 끌 수 있습니다.",
    ja: "エージェント追跡がオフのため、エージェントは表示されません。オンにすると ~/.claude/settings.json にフックを追加し、ymux がエージェントとサブエージェントを表示できます。設定でオフに戻せます。",
    zh: "代理跟踪已关闭，因此这里不会列出代理。开启后会向 ~/.claude/settings.json 添加钩子，ymux 才能显示代理和子代理。可以在设置中再次关闭。",
    hi: "एजेंट ट्रैकिंग बंद है, इसलिए कोई एजेंट नहीं दिखता। चालू करने पर ~/.claude/settings.json में हुक जुड़ते हैं ताकि ymux एजेंट और उप-एजेंट दिखा सके। इसे सेटिंग्स में फिर से बंद किया जा सकता है।",
    es: "El seguimiento de agentes está desactivado, por eso no se lista ningún agente. Al activarlo se añaden hooks a ~/.claude/settings.json para que ymux pueda mostrar agentes y subagentes. Puedes desactivarlo de nuevo en Ajustes.",
    fr: "Le suivi des agents est désactivé, aucun agent n'est donc listé. L'activer ajoute des hooks à ~/.claude/settings.json pour que ymux puisse afficher les agents et sous-agents. Vous pouvez le désactiver dans les réglages.",
    ar: "تتبّع الوكلاء متوقّف، لذا لا تظهر أي وكلاء هنا. تشغيله يضيف خطافات إلى ~/.claude/settings.json ليتمكّن ymux من عرض الوكلاء والوكلاء الفرعيين. يمكنك إيقافه مجدداً من الإعدادات.",
    pt: "O acompanhamento de agentes está desativado, por isso nenhum agente é listado. Ativá-lo adiciona hooks ao ~/.claude/settings.json para que o ymux possa mostrar agentes e subagentes. Você pode desativá-lo novamente em Configurações.",
    ru: "Отслеживание агентов выключено, поэтому агенты здесь не показаны. При включении в ~/.claude/settings.json добавляются хуки, чтобы ymux мог показывать агентов и субагентов. Выключить снова можно в настройках.",
    tr: "Ajan izleme kapalı, bu yüzden burada ajan listelenmiyor. Açmak ~/.claude/settings.json dosyasına kanca ekler, böylece ymux ajanları ve alt ajanları gösterebilir. Ayarlar'dan yeniden kapatabilirsiniz.",
    de: "Agenten-Tracking ist aus, daher werden hier keine Agenten aufgeführt. Beim Einschalten werden Hooks in ~/.claude/settings.json eingetragen, damit ymux Agenten und Subagenten anzeigen kann. In den Einstellungen wieder abschaltbar.",
    vi: "Theo dõi tác tử đang tắt nên không có tác tử nào được liệt kê. Bật lên sẽ thêm hook vào ~/.claude/settings.json để ymux hiển thị tác tử và tác tử con. Bạn có thể tắt lại trong Cài đặt.",
  },
