  "git.checkoutTrackTitle": {
    en: "Create branch {branch} tracking {remote} and check it out?", ko: "{remote}를 추적하는 브랜치 {branch}를 만들고 체크아웃할까요?", ja: "{remote} を追跡するブランチ {branch} を作成してチェックアウトしますか？",
    zh: "创建跟踪 {remote} 的分支 {branch} 并检出？", hi: "{remote} को ट्रैक करने वाली ब्रांच {branch} बनाकर चेकआउट करें?", es: "¿Crear la rama {branch} que sigue a {remote} y extraerla?",
    fr: "Créer la branche {branch} qui suit {remote} et l'extraire ?", ar: "إنشاء الفرع {branch} الذي يتتبع {remote} وسحبه؟", pt: "Criar o branch {branch} rastreando {remote} e fazer checkout?",
    ru: "Создать ветку {branch}, отслеживающую {remote}, и переключиться на неё?", tr: "{remote} dalını izleyen {branch} dalı oluşturulup etkinleştirilsin mi?", de: "Branch {branch} erstellen, der {remote} folgt, und auschecken?", vi: "Tạo nhánh {branch} theo dõi {remote} và checkout?",
  },
  "git.checkoutLocalNotRemote": {
    en: "This checks out your local {branch}, which may differ from {remote}.", ko: "로컬 {branch}를 체크아웃합니다. {remote}와 다를 수 있습니다.", ja: "ローカルの {branch} をチェックアウトします。{remote} とは異なる場合があります。",
    zh: "这会检出你本地的 {branch}，它可能与 {remote} 不同。", hi: "यह आपकी लोकल {branch} चेकआउट करता है, जो {remote} से अलग हो सकती है।", es: "Se extrae tu {branch} local, que puede diferir de {remote}.",
    fr: "Ceci extrait votre {branch} locale, qui peut différer de {remote}.", ar: "سيُسحب {branch} المحلي لديك، وقد يختلف عن {remote}.", pt: "Isto faz checkout do seu {branch} local, que pode diferir de {remote}.",
    ru: "Будет извлечена ваша локальная {branch}; она может отличаться от {remote}.", tr: "Yerel {branch} dalınız etkinleştirilir; {remote} ile farklı olabilir.", de: "Ausgecheckt wird Ihr lokaler {branch}, der von {remote} abweichen kann.", vi: "Thao tác này checkout {branch} cục bộ của bạn, có thể khác {remote}.",
  },
  "git.checkoutCarried": {
    en: "Nothing is discarded: these {n} uncommitted changes stay in the folder and come with you to {branch}. If any would be overwritten, git refuses the checkout.", ko: "버려지는 것은 없습니다. 커밋하지 않은 변경 {n}개는 폴더에 그대로 남아 {branch}로 함께 옮겨집니다. 덮어써질 변경이 있으면 git이 체크아웃을 거부합니다.", ja: "破棄されるものはありません。未コミットの変更 {n} 件はフォルダーに残り、{branch} へそのまま持ち越されます。上書きされる変更がある場合、git はチェックアウトを拒否します。",
    zh: "不会丢弃任何内容：这 {n} 个未提交的更改保留在文件夹中，并随你带到 {branch}。如有更改会被覆盖，git 会拒绝检出。", hi: "कुछ भी नहीं हटेगा: ये {n} बिना कमिट किए बदलाव फ़ोल्डर में रहेंगे और आपके साथ {branch} पर जाएँगे। अगर कोई बदलाव ओवरराइट होता, तो git चेकआउट से मना कर देता है।", es: "No se descarta nada: estos {n} cambios sin confirmar se quedan en la carpeta y pasan contigo a {branch}. Si alguno fuera a sobrescribirse, git rechaza el cambio de rama.",
    fr: "Rien n'est perdu : ces {n} modifications non validées restent dans le dossier et vous suivent sur {branch}. Si l'une devait être écrasée, git refuse l'extraction.", ar: "لن يُتجاهل شيء: تبقى هذه التغييرات غير المُودعة ({n}) في المجلد وتنتقل معك إلى {branch}. إذا كان أيٌّ منها سيُستبدل، يرفض git السحب.", pt: "Nada é descartado: estas {n} alterações não confirmadas ficam na pasta e vão com você para {branch}. Se alguma fosse sobrescrita, o git recusa o checkout.",
    ru: "Ничего не теряется: эти {n} незакоммиченных изменений остаются в папке и переходят с вами на {branch}. Если какое-то из них было бы перезаписано, git откажется переключаться.", tr: "Hiçbir şey atılmaz: kaydedilmemiş bu {n} değişiklik klasörde kalır ve sizinle {branch} dalına geçer. Üzerine yazılacak bir değişiklik varsa git işlemi reddeder.", de: "Nichts wird verworfen: Diese {n} nicht committeten Änderungen bleiben im Ordner und kommen mit auf {branch}. Würde eine überschrieben, verweigert Git das Auschecken.", vi: "Không mất gì: {n} thay đổi chưa commit này vẫn ở trong thư mục và đi cùng bạn sang {branch}. Nếu có thay đổi nào bị ghi đè, git sẽ từ chối checkout.",
  },
  "git.checkoutStranded": {
    en: "HEAD is detached, and these {n} commits are on no branch. After the checkout nothing points to them; only the reflog can bring them back:", ko: "HEAD가 분리되어 있고, 이 커밋 {n}개는 어떤 브랜치에도 없습니다. 체크아웃하면 이 커밋을 가리키는 것이 없어지며 reflog로만 되살릴 수 있습니다:", ja: "HEAD が切り離されており、次の {n} 件のコミットはどのブランチにもありません。チェックアウト後はどこからも参照されず、reflog でしか戻せません:",
    zh: "HEAD 处于游离状态，这 {n} 个提交不在任何分支上。检出后将没有任何引用指向它们，只能通过 reflog 找回：", hi: "HEAD अलग है, और ये {n} कमिट किसी ब्रांच पर नहीं हैं। चेकआउट के बाद कुछ भी इनकी ओर इशारा नहीं करेगा; केवल reflog से इन्हें वापस लाया जा सकता है:", es: "HEAD está separado y estos {n} commits no están en ninguna rama. Tras el cambio nada apuntará a ellos; solo el reflog podrá recuperarlos:",
    fr: "HEAD est détaché et ces {n} commits ne sont sur aucune branche. Après l'extraction, plus rien ne pointe vers eux ; seul le reflog peut les récupérer :", ar: "HEAD منفصل، وهذه الإيداعات ({n}) ليست على أي فرع. بعد السحب لن يشير إليها شيء؛ ولا يستعيدها إلا reflog:", pt: "HEAD está desanexado e estes {n} commits não estão em nenhum branch. Após o checkout nada apontará para eles; só o reflog poderá recuperá-los:",
    ru: "HEAD отсоединён, и эти {n} коммитов не входят ни в одну ветку. После переключения на них ничто не будет указывать; вернуть их можно только через reflog:", tr: "HEAD ayrık ve bu {n} commit hiçbir dalda değil. İşlemden sonra onları hiçbir şey göstermez; yalnızca reflog ile geri getirilebilirler:", de: "HEAD ist losgelöst, und diese {n} Commits liegen auf keinem Branch. Nach dem Auschecken zeigt nichts mehr auf sie; nur das Reflog holt sie zurück:", vi: "HEAD đang tách rời và {n} commit này không thuộc nhánh nào. Sau khi checkout sẽ không còn gì trỏ tới chúng; chỉ reflog mới lấy lại được:",
  },
