    zh: "其中被忽略的文件也会被删除，即使不强制：", hi: "इसमें अनदेखी की गई फ़ाइलें भी हट जाएँगी, बिना बलपूर्वक हटाए भी:", es: "Los archivos ignorados que contiene también se borran, aun sin forzar:",
    fr: "Les fichiers ignorés qu'il contient sont aussi supprimés, même sans forcer :", ar: "تُحذف الملفات المتجاهَلة فيه أيضًا، حتى دون فرض:", pt: "Os arquivos ignorados nele também são excluídos, mesmo sem forçar:",
