  "settings.accounts.heading": {
    en: "Accounts", ko: "계정", ja: "アカウント",
    zh: "账户", hi: "खाते", es: "Cuentas",
    fr: "Comptes", ar: "الحسابات", pt: "Contas",
    ru: "Аккаунты", tr: "Hesaplar", de: "Konten", vi: "Tài khoản",
  },
  "settings.accounts.hint": {
    en: "Add a login for each Claude Code / Codex account you use. Press “+” and pick Claude Code or Codex to choose the account (or add a new one) — the agent asks you to sign in the first time it runs under a new account. ymux keeps each account's login in its own folder, so nothing needs configuring here. Renaming, colours and deleting live below.",
    ko: "사용하는 Claude Code / Codex 계정마다 로그인을 추가하세요. “+” 버튼에서 Claude Code나 Codex를 고르면 어느 계정으로 실행할지 선택하거나 새 계정을 추가할 수 있고, 새 계정으로 처음 실행할 때 에이전트가 로그인을 요청합니다. 계정마다 로그인 폴더는 ymux가 알아서 따로 관리하므로 여기서 따로 설정할 것은 없습니다. 아래에서 이름·색상 변경과 삭제만 하면 됩니다.",
    ja: "使用する Claude Code / Codex のアカウントごとにログインを追加します。「+」から Claude Code または Codex を選ぶと、起動するアカウントを選択したり新しいアカウントを追加したりできます。新しいアカウントで初めて起動するとエージェントがサインインを求めます。ログインフォルダは ymux がアカウントごとに管理するので、ここで設定する必要はありません。名前・色の変更と削除は下で行えます。",
    zh: "为你使用的每个 Claude Code / Codex 账户添加登录。点击“+”并选择 Claude Code 或 Codex，即可选择用哪个账户启动（或添加新账户）——首次以新账户运行时代理会要求登录。ymux 会为每个账户单独管理登录文件夹，这里无需任何配置。下方可重命名、改颜色或删除。",
    hi: "आप जिन Claude Code / Codex खातों का उपयोग करते हैं, हर एक के लिए लॉगिन जोड़ें। “+” दबाकर Claude Code या Codex चुनें, फिर खाता चुनें (या नया जोड़ें) — नए खाते में पहली बार चलने पर एजेंट साइन इन करने को कहेगा। ymux हर खाते का लॉगिन अलग फ़ोल्डर में रखता है, इसलिए यहाँ कुछ सेट करने की ज़रूरत नहीं। नाम, रंग और हटाना नीचे है।",
    es: "Añade un inicio de sesión por cada cuenta de Claude Code / Codex que uses. Pulsa “+” y elige Claude Code o Codex para escoger la cuenta (o añadir una nueva); la primera vez que el agente se ejecute con una cuenta nueva te pedirá iniciar sesión. ymux guarda el inicio de sesión de cada cuenta en su propia carpeta, así que aquí no hay nada que configurar. Abajo puedes renombrar, cambiar colores y eliminar.",
    fr: "Ajoutez une connexion pour chaque compte Claude Code / Codex que vous utilisez. Appuyez sur « + » et choisissez Claude Code ou Codex pour sélectionner le compte (ou en ajouter un) — l’agent vous demande de vous connecter la première fois qu’il tourne sous un nouveau compte. ymux range la connexion de chaque compte dans son propre dossier : rien à configurer ici. Renommer, colorer et supprimer se fait ci-dessous.",
    ar: "أضف تسجيل دخول لكل حساب Claude Code / Codex تستخدمه. اضغط “+” واختر Claude Code أو Codex لتحديد الحساب (أو إضافة حساب جديد) — يطلب منك الوكيل تسجيل الدخول في أول تشغيل بحساب جديد. يحفظ ymux تسجيل دخول كل حساب في مجلد خاص به، فلا شيء يحتاج إلى إعداد هنا. إعادة التسمية والألوان والحذف أدناه.",
    pt: "Adicione um login para cada conta do Claude Code / Codex que você usa. Pressione “+” e escolha Claude Code ou Codex para selecionar a conta (ou adicionar uma nova) — o agente pede para entrar na primeira vez que roda com uma conta nova. O ymux guarda o login de cada conta em uma pasta própria, então não há nada para configurar aqui. Renomear, cores e excluir ficam abaixo.",
    ru: "Добавьте вход для каждого аккаунта Claude Code / Codex, которым пользуетесь. Нажмите «+» и выберите Claude Code или Codex, чтобы выбрать аккаунт (или добавить новый) — при первом запуске под новым аккаунтом агент попросит войти. ymux хранит вход каждого аккаунта в отдельной папке, поэтому настраивать здесь ничего не нужно. Переименование, цвета и удаление — ниже.",
    tr: "Kullandığınız her Claude Code / Codex hesabı için bir giriş ekleyin. “+” düğmesine basıp Claude Code veya Codex'i seçerek hesabı seçin (ya da yeni ekleyin) — ajan yeni bir hesapla ilk çalıştığında oturum açmanızı ister. ymux her hesabın girişini ayrı bir klasörde tutar; burada ayarlanacak bir şey yok. Yeniden adlandırma, renkler ve silme aşağıda.",
    de: "Fügen Sie für jedes Claude-Code-/Codex-Konto, das Sie nutzen, einen Login hinzu. Über „+“ und Claude Code oder Codex wählen Sie das Konto (oder fügen ein neues hinzu) – beim ersten Start unter einem neuen Konto fragt der Agent nach der Anmeldung. ymux legt den Login jedes Kontos in einem eigenen Ordner ab, hier ist also nichts einzurichten. Umbenennen, Farben und Löschen finden Sie unten.",
    vi: "Thêm đăng nhập cho mỗi tài khoản Claude Code / Codex bạn dùng. Nhấn “+” rồi chọn Claude Code hoặc Codex để chọn tài khoản (hoặc thêm tài khoản mới) — lần đầu chạy bằng tài khoản mới, agent sẽ yêu cầu đăng nhập. ymux giữ đăng nhập của mỗi tài khoản trong thư mục riêng nên không cần cấu hình gì ở đây. Đổi tên, màu và xóa ở bên dưới.",
  },
