  "autoContinue.toggle": {
    en: "Answer Claude Code's questions automatically", ko: "Claude Code의 질문에 자동으로 답하기", ja: "Claude Code の質問に自動で答える",
    zh: "自动回答 Claude Code 的提问", hi: "Claude Code के सवालों का अपने-आप जवाब दें", es: "Responder automáticamente a las preguntas de Claude Code",
    fr: "Répondre automatiquement aux questions de Claude Code", ar: "الإجابة تلقائيًا عن أسئلة Claude Code", pt: "Responder automaticamente às perguntas do Claude Code",
    ru: "Отвечать на вопросы Claude Code автоматически", tr: "Claude Code'un sorularını otomatik yanıtla", de: "Fragen von Claude Code automatisch beantworten", vi: "Tự động trả lời câu hỏi của Claude Code",
  },
  "autoContinue.hint": {
    en: "Claude Code only. While on, each question Claude asks gets the option marked \"(Recommended)\"; if none is marked, Claude is told to decide itself. Turns off when yMux restarts. The recommended option is not always the right one.", ko: "Claude Code 전용입니다. 켜져 있는 동안 Claude의 질문에는 \"(Recommended)\"로 표시된 선택지가 자동 선택되며, 표시된 것이 없으면 Claude가 직접 판단하도록 안내합니다. yMux를 다시 시작하면 꺼집니다. 추천 선택지가 항상 옳은 것은 아닙니다.", ja: "Claude Code 専用です。オン中は、Claude の質問に「(Recommended)」付きの選択肢が自動で選ばれ、付いていなければ Claude 自身で判断するよう伝えます。yMux を再起動するとオフに戻ります。推奨の選択肢が常に正しいとは限りません。",
    zh: "仅适用于 Claude Code。开启后，Claude 的每个提问都会自动选择标有“(Recommended)”的选项；若没有标记，则告知 Claude 自行决定。重启 yMux 后自动关闭。推荐选项并不总是正确的。", hi: "केवल Claude Code के लिए। चालू रहने पर Claude के हर सवाल में \"(Recommended)\" वाला विकल्प चुना जाता है; कोई चिह्नित न हो तो Claude को खुद तय करने को कहा जाता है। yMux दोबारा शुरू करने पर यह बंद हो जाता है। सुझाया गया विकल्प हमेशा सही नहीं होता।", es: "Solo para Claude Code. Mientras está activado, cada pregunta recibe la opción marcada con \"(Recommended)\"; si ninguna lo está, se le indica a Claude que decida por su cuenta. Se desactiva al reiniciar yMux. La opción recomendada no siempre es la correcta.",
    fr: "Claude Code uniquement. Activé, chaque question reçoit l'option marquée « (Recommended) » ; si aucune ne l'est, Claude doit décider lui-même. Se désactive au redémarrage de yMux. L'option recommandée n'est pas toujours la bonne.", ar: "لـ Claude Code فقط. عند التفعيل يُختار الخيار المعلَّم بـ \"(Recommended)\" لكل سؤال، وإن لم يوجد خيار معلَّم يُطلب من Claude أن يقرر بنفسه. يتوقف عند إعادة تشغيل yMux. الخيار الموصى به ليس صحيحًا دائمًا.", pt: "Somente Claude Code. Ativado, cada pergunta recebe a opção marcada com \"(Recommended)\"; se nenhuma estiver marcada, o Claude é instruído a decidir sozinho. Desliga ao reiniciar o yMux. A opção recomendada nem sempre é a certa.",
    ru: "Только для Claude Code. Пока включено, на каждый вопрос выбирается вариант с пометкой «(Recommended)»; если пометки нет, Claude должен решить сам. Выключается при перезапуске yMux. Рекомендуемый вариант не всегда верный.", tr: "Yalnızca Claude Code için. Açıkken her soruya \"(Recommended)\" işaretli seçenek verilir; işaretli yoksa Claude'a kendisinin karar vermesi söylenir. yMux yeniden başlatılınca kapanır. Önerilen seçenek her zaman doğru değildir.", de: "Nur für Claude Code. Solange aktiv, erhält jede Frage die mit „(Recommended)“ markierte Option; ist keine markiert, soll Claude selbst entscheiden. Wird beim Neustart von yMux ausgeschaltet. Die empfohlene Option ist nicht immer die richtige.", vi: "Chỉ dành cho Claude Code. Khi bật, mỗi câu hỏi sẽ nhận lựa chọn được đánh dấu \"(Recommended)\"; nếu không có, Claude được yêu cầu tự quyết định. Tự tắt khi khởi động lại yMux. Lựa chọn được đề xuất không phải lúc nào cũng đúng.",
  },
