    hi: "{lane}: प्रॉम्प्ट लिख दिया गया। भेजने के लिए पेन में Enter दबाएँ।", es: "{lane}: prompt escrito. Pulsa Intro en el panel para enviarlo.", fr: "{lane} : prompt saisi. Appuyez sur Entrée dans le volet pour l’envoyer.", ar: "{lane}: تمت كتابة الموجّه. اضغط Enter في اللوحة لإرساله.",
    pt: "{lane}: prompt digitado. Pressione Enter no painel para enviá-lo.", ru: "{lane}: промпт введён. Нажмите Enter в панели, чтобы отправить.", tr: "{lane}: istem yazıldı. Göndermek için bölmede Enter’a basın.", de: "{lane}: Prompt eingetippt. Drücke im Pane Enter, um ihn zu senden.",
