    ru: "Удалить эти ветки? Удаляются только полностью слитые (git branch -d); остальные будут отклонены и сохранены.\n\n{list}", tr: "Bu dallar silinsin mi? Yalnızca tamamen birleştirilmiş dallar silinir (git branch -d); diğerleri reddedilir ve korunur.\n\n{list}", de: "Diese Branches löschen? Nur vollständig gemergte werden entfernt (git branch -d); die übrigen werden abgelehnt und bleiben.\n\n{list}",
    vi: "Xóa các nhánh này? Chỉ nhánh đã hợp nhất hoàn toàn mới bị xóa (git branch -d); các nhánh còn lại bị từ chối và được giữ.\n\n{list}",
